CREATE TABLE public.ai_sponsor_policy (id boolean PRIMARY KEY DEFAULT true CHECK(id), enabled boolean NOT NULL DEFAULT false, emergency_stop boolean NOT NULL DEFAULT true, openai_enabled boolean NOT NULL DEFAULT false, claude_enabled boolean NOT NULL DEFAULT false, allow_fallback boolean NOT NULL DEFAULT false, intro_usd numeric NOT NULL DEFAULT 0 CHECK(intro_usd >= 0), daily_questions integer NOT NULL DEFAULT 0 CHECK(daily_questions >= 0), per_user_usd numeric NOT NULL DEFAULT 0 CHECK(per_user_usd >= 0), total_usd numeric NOT NULL DEFAULT 0 CHECK(total_usd >= 0), eligible_since timestamptz, key_owner uuid, claude_tasks text[] NOT NULL DEFAULT '{}', updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.ai_sponsor_policy TO authenticated;
GRANT ALL ON public.ai_sponsor_policy TO service_role;
ALTER TABLE public.ai_sponsor_policy ENABLE ROW LEVEL SECURITY;
CREATE POLICY sponsor_admin_read ON public.ai_sponsor_policy FOR SELECT TO authenticated USING(public.is_usage_admin());
CREATE POLICY sponsor_admin_insert ON public.ai_sponsor_policy FOR INSERT TO authenticated WITH CHECK(public.is_usage_admin());
CREATE POLICY sponsor_admin_update ON public.ai_sponsor_policy FOR UPDATE TO authenticated USING(public.is_usage_admin()) WITH CHECK(public.is_usage_admin());
CREATE TABLE public.ai_intro_wallets (user_id uuid PRIMARY KEY, granted_usd numeric NOT NULL CHECK(granted_usd >= 0), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.ai_intro_wallets TO authenticated;
GRANT ALL ON public.ai_intro_wallets TO service_role;
ALTER TABLE public.ai_intro_wallets ENABLE ROW LEVEL SECURITY;
CREATE POLICY intro_wallet_read ON public.ai_intro_wallets FOR SELECT TO authenticated USING(user_id = auth.uid() OR public.is_usage_admin());
CREATE TABLE public.ai_spend_reservations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, request_id uuid NOT NULL, attempt integer NOT NULL CHECK(attempt IN(1,2)), provider text NOT NULL CHECK(provider IN('chatgpt','claude')), model text NOT NULL, scope text NOT NULL CHECK(scope IN('chat','diagram','picture')), reserved_usd numeric NOT NULL CHECK(reserved_usd > 0), settled_usd numeric, state text NOT NULL DEFAULT 'reserved' CHECK(state IN('reserved','uncertain','settled')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id, request_id, attempt));
GRANT SELECT ON public.ai_spend_reservations TO authenticated;
GRANT ALL ON public.ai_spend_reservations TO service_role;
ALTER TABLE public.ai_spend_reservations ENABLE ROW LEVEL SECURITY;
CREATE POLICY spend_read ON public.ai_spend_reservations FOR SELECT TO authenticated USING(user_id = auth.uid() OR public.is_usage_admin());
CREATE INDEX ai_spend_user_time ON public.ai_spend_reservations(user_id,created_at);
ALTER TABLE public.visitor_ai_settings ADD COLUMN funding_mode text NOT NULL DEFAULT 'visitor' CHECK(funding_mode IN('visitor','sponsored'));
ALTER TABLE public.visitor_ai_events ADD COLUMN request_scope text NOT NULL DEFAULT 'chat' CHECK(request_scope IN('chat','diagram','picture'));
ALTER TABLE public.visitor_ai_events ADD COLUMN funding_source text NOT NULL DEFAULT 'visitor';
ALTER TABLE public.visitor_ai_events ADD COLUMN request_id uuid;
UPDATE public.visitor_ai_events SET request_scope = CASE WHEN buddy='picture' THEN 'picture' WHEN model='gemini-3.8-flash' THEN 'diagram' ELSE 'chat' END;
CREATE FUNCTION public.ensure_intro_allowance(_user uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.ai_sponsor_policy; BEGIN SELECT * INTO p FROM public.ai_sponsor_policy WHERE id=true; IF NOT FOUND OR NOT p.enabled OR p.emergency_stop OR p.intro_usd <= 0 OR p.eligible_since IS NULL THEN RETURN; END IF; IF EXISTS(SELECT 1 FROM auth.users WHERE id=_user AND email_confirmed_at IS NOT NULL AND created_at >= p.eligible_since) AND EXISTS(SELECT 1 FROM public.visitor_ai_settings WHERE user_id=_user) THEN INSERT INTO public.ai_intro_wallets(user_id,granted_usd) VALUES(_user,p.intro_usd) ON CONFLICT(user_id) DO NOTHING; END IF; END; $$;
REVOKE ALL ON FUNCTION public.ensure_intro_allowance(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.ensure_intro_allowance(uuid) TO service_role;
CREATE FUNCTION public.reserve_sponsor_spend(_user uuid,_request uuid,_attempt integer,_provider text,_model text,_scope text,_cost numeric) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.ai_sponsor_policy; w public.ai_intro_wallets; used_user numeric; used_site numeric; questions integer; rid uuid; BEGIN SELECT * INTO p FROM public.ai_sponsor_policy WHERE id=true FOR UPDATE; IF NOT FOUND OR NOT p.enabled OR p.emergency_stop THEN RAISE EXCEPTION 'Sponsored AI is currently off.'; END IF; IF _scope='picture' THEN RAISE EXCEPTION 'Sponsored pictures are not enabled.'; END IF; IF _cost IS NULL OR _cost<=0 OR _cost>10 THEN RAISE EXCEPTION 'Request pricing is unavailable.'; END IF; IF (_provider='chatgpt' AND NOT p.openai_enabled) OR (_provider='claude' AND NOT p.claude_enabled) OR _provider NOT IN('chatgpt','claude') THEN RAISE EXCEPTION 'This provider is disabled.'; END IF; IF _attempt=2 AND (NOT p.allow_fallback OR _provider<>'claude') THEN RAISE EXCEPTION 'Fallback is disabled.'; END IF; IF p.key_owner IS NULL OR NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=p.key_owner AND role='admin') OR NOT EXISTS(SELECT 1 FROM public.visitor_ai_keys WHERE user_id=p.key_owner AND provider=_provider) THEN RAISE EXCEPTION 'Administrator provider access is unavailable.'; END IF; IF NOT EXISTS(SELECT 1 FROM public.visitor_ai_settings WHERE user_id=_user AND funding_mode='sponsored') THEN RAISE EXCEPTION 'Choose introductory allowance in your account first.'; END IF; PERFORM public.ensure_intro_allowance(_user); SELECT * INTO w FROM public.ai_intro_wallets WHERE user_id=_user FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'No introductory allowance is available for this account.'; END IF; IF EXISTS(SELECT 1 FROM public.ai_spend_reservations WHERE user_id=_user AND request_id=_request AND attempt=_attempt) THEN RAISE EXCEPTION 'This question has already been submitted.'; END IF; IF _attempt=2 AND NOT EXISTS(SELECT 1 FROM public.ai_spend_reservations WHERE user_id=_user AND request_id=_request AND attempt=1 AND provider='chatgpt' AND state='settled' AND settled_usd=0) THEN RAISE EXCEPTION 'The first request has not been safely resolved.'; END IF; SELECT coalesce(sum(coalesce(settled_usd,reserved_usd)),0) INTO used_user FROM public.ai_spend_reservations WHERE user_id=_user; SELECT coalesce(sum(coalesce(settled_usd,reserved_usd)),0) INTO used_site FROM public.ai_spend_reservations; IF used_user+_cost>least(w.granted_usd,p.per_user_usd) OR used_site+_cost>p.total_usd THEN RAISE EXCEPTION 'Your introductory allowance or the site budget cannot cover this request.'; END IF; SELECT count(DISTINCT request_id) INTO questions FROM public.ai_spend_reservations WHERE user_id=_user AND scope='chat' AND created_at >= date_trunc('day',now()); IF _scope='chat' AND _attempt=1 AND questions>=p.daily_questions THEN RAISE EXCEPTION 'Your daily question limit has been reached. Please try tomorrow.'; END IF; INSERT INTO public.ai_spend_reservations(user_id,request_id,attempt,provider,model,scope,reserved_usd) VALUES(_user,_request,_attempt,_provider,_model,_scope,_cost) RETURNING id INTO rid; RETURN rid; END; $$;
REVOKE ALL ON FUNCTION public.reserve_sponsor_spend(uuid,uuid,integer,text,text,text,numeric) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.reserve_sponsor_spend(uuid,uuid,integer,text,text,text,numeric) TO service_role;
CREATE FUNCTION public.settle_sponsor_spend(_id uuid,_cost numeric) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF _cost IS NULL THEN UPDATE public.ai_spend_reservations SET state='uncertain' WHERE id=_id AND state='reserved'; ELSE IF _cost<0 THEN RAISE EXCEPTION 'Invalid cost'; END IF; UPDATE public.ai_spend_reservations SET settled_usd=_cost,state='settled' WHERE id=_id AND state='reserved'; END IF; END; $$;
REVOKE ALL ON FUNCTION public.settle_sponsor_spend(uuid,numeric) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.settle_sponsor_spend(uuid,numeric) TO service_role;
CREATE FUNCTION public.sponsor_balance(_user uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.ai_sponsor_policy; granted numeric; spent numeric; site_spent numeric; BEGIN IF auth.role()<>'service_role' AND _user IS DISTINCT FROM auth.uid() AND NOT public.is_usage_admin() THEN RAISE EXCEPTION 'Access denied'; END IF; SELECT * INTO p FROM public.ai_sponsor_policy WHERE id=true; SELECT granted_usd INTO granted FROM public.ai_intro_wallets WHERE user_id=_user; SELECT coalesce(sum(coalesce(settled_usd,reserved_usd)),0) INTO spent FROM public.ai_spend_reservations WHERE user_id=_user; SELECT coalesce(sum(coalesce(settled_usd,reserved_usd)),0) INTO site_spent FROM public.ai_spend_reservations; RETURN jsonb_build_object('granted',coalesce(granted,0),'used',spent,'remaining',greatest(0,least(coalesce(granted,0),coalesce(p.per_user_usd,0))-spent),'available',coalesce(p.enabled AND NOT p.emergency_stop,false),'dailyLimit',coalesce(p.daily_questions,0),'siteRemaining',CASE WHEN public.is_usage_admin() OR auth.role()='service_role' THEN greatest(0,coalesce(p.total_usd,0)-site_spent) ELSE NULL END); END; $$;
REVOKE ALL ON FUNCTION public.sponsor_balance(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.sponsor_balance(uuid) TO authenticated,service_role;
CREATE FUNCTION public.visitor_daily_totals() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('questions',count(*) FILTER(WHERE request_scope='chat'),'diagrams',count(*) FILTER(WHERE request_scope='diagram'),'pictures',count(*) FILTER(WHERE request_scope='picture')) FROM public.visitor_ai_events WHERE user_id=auth.uid() AND (created_at AT TIME ZONE coalesce((SELECT timezone FROM public.visitor_ai_settings WHERE user_id=auth.uid()),'UTC'))::date=(now() AT TIME ZONE coalesce((SELECT timezone FROM public.visitor_ai_settings WHERE user_id=auth.uid()),'UTC'))::date; $$;
REVOKE ALL ON FUNCTION public.visitor_daily_totals() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.visitor_daily_totals() TO authenticated,service_role;